  'help.type.cant_login': 'Ne morem se prijaviti',
  'help.type.email_issue': 'Težava z emailom',
  'help.type.security': 'Varnost',
  'help.type.other': 'Drugo',
  'help.faq.cantLogin.q': 'Ne morem dostopati do svojega računa',
  'help.faq.cantLogin.a': 'Preveri, ali uporabljaš pravilen email in geslo. Če si pozabil geslo, klikni na "Pozabil si geslo?" na prijavni strani. Če težava še vedno traja, ustvari podporni tiket.',
  'help.faq.notReceiving.q': 'Ne prejemam emailov',
  'help.faq.notReceiving.a': 'Najprej preveri mapo za neželeno pošto. Prepričaj se, da tvoj prostor za shranjevanje ni poln. Če težava še vedno traja, potrdi, da ima pošiljatelj pravilen naslov in ustvari tiket.',
  'help.faq.cantSend.q': 'Ne morem poslati emailov',
  'help.faq.cantSend.a': 'Preveri svojo internetno povezavo in ali je naslov prejemnika pravilen. Preveri, ali priponke ne presegajo 25MB. Poskusi znova čez nekaj minut.',
  'help.faq.forgotPassword.q': 'Pozabil sem geslo',
  'help.faq.forgotPassword.a': 'Na prijavni strani klikni na "Pozabil si geslo?" in sledi navodilom za ponastavitev gesla preko emaila za obnovitev.',
  'help.faq.accountSecurity.q': 'Mislim, da je moj račun ogrožen',
  'help.faq.accountSecurity.a': 'Takoj spremeni svoje geslo. Preveri mapo Poslano za sporočila, ki jih nisi poslal. Aktiviraj dvostopenjsko avtentikacijo v Nastavitvah > Varnost. Če je potrebno, ustvari nujni tiket.',
  'help.faq.appAccess.q': 'Kako dostopam do aplikacije na telefonu?',
  'help.faq.appAccess.a': 'Dostopaš lahko do Chatyy preko brskalnika na chatyy.com.br, ali preneseš našo aplikacijo iz trgovine aplikacij na tvojem napravi.',
  'privacy.title': 'Politika zasebnosti',
  'privacy.subtitle': 'Kako ščitimo in obravnavamo tvoje podatke',
  'privacy.lastUpdated': 'Zadnja posodobitev: Marec 2026',
  'privacy.dataCollection.title': 'Zbiranje podatkov',
  'privacy.dataCollection.body': 'Zbiramo le informacije, potrebne za storitev email: tvoje ime, email naslov in vsebino poslanih in prejetih sporočil. Tvojih osebnih podatkov ne prodajamo niti ne delimo s tretjimi osebami za namene trženja.',
  'privacy.dataUsage.title': 'Kako uporabljamo tvoje podatke',
  'privacy.dataUsage.body': 'Tvoji podatki se uporabljajo izključno za delovanje in izboljšanje storitve email, vključno z dostavo sporočil, filtriranjem neželene pošte, funkcijami AI (s tvojim soglasjem) in varnostjo računa.',
  'privacy.dataSecurity.title': 'Varnost podatkov',
  'privacy.dataSecurity.body': 'Uporabljamo industrijske standarde šifriranja (TLS/SSL) za vse podatke v prenosu in v mirovanju. Seje so zaščitene s šifriranimi žetoni in zaščito CSRF. Redno preverjamo naše varnostne prakse.',
  'privacy.cookies.title': 'Piškotki in lokalno shranjevanje',
  'privacy.cookies.body': 'Uporabljamo nujne piškotke in lokalno shranjevanje za ohranjanje tvoje seje, zapomnitev tvojih nastavitev (tema, jezik) in zagotavljanje gladke izkušnje. Ne uporabljamo piškotkov za sledenje tretjih oseb.',
  'privacy.thirdParties.title': 'Storitve tretjih oseb',
  'privacy.thirdParties.body': 'Lahko uporabljamo storitve tretjih oseb za specifične funkcionalnosti, kot so AI (Anthropic Claude) in obvestila. Te storitve sledijo svojim lastnim politikam zasebnosti in obdelujejo le minimalne potrebne podatke.',
  'privacy.rights.title': 'Tvoje pravice',
  'privacy.rights.body': 'Imaš pravico do dostopa, popravka, izvoza ali izbrisa svojih osebnih podatkov kadarkoli. Svoje podatke lahko upravljaš v Nastavitvah ali tako, da kontaktiraš našo podporo.',
  'privacy.contact.title': 'Kontaktiraj nas',
  'privacy.contact.body': 'Za vprašanja o zasebnosti ali zahteve po podatkih, nas kontaktiraj na privacy@chatyy.com.br. Odgovorili bomo v 30 dneh.',
  'terms.title': 'Pogoji storitve',
  'terms.subtitle': 'Smernice za uporabo Chatyy',
  'terms.lastUpdated': 'Zadnja posodobitev: Marec 2026',
  'terms.acceptance.title': 'Sprejem pogojev',
  'terms.acceptance.body': 'Z dostopom ali uporabo Chatyy se strinjaš s temi pogoji storitve. Če se ne strinjaš z delom teh pogojev, ne uporabljaj storitve.',
  'terms.services.title': 'Opis storitev',
  'terms.services.body': 'Chatyy nudi storitve komunikacije preko emaila, vključno s pošiljanjem, prejemanjem in upravljanjem emailov, poleg funkcij AI, integracije s koledarjem in videokonferencami.',
  'terms.accounts.title': 'Uporabniški računi',
  'terms.accounts.body': 'Ti si odgovoren za ohranjanje varnosti svojih poverilnic. Ne deli svojega gesla in ne dovoli nepooblaščenega dostopa do svojega računa. Za uporabo te storitve moraš imeti vsaj 13 let.',
  'terms.conduct.title': 'Sprejemljivo ravnanje',
  'terms.conduct.body': 'Strinjaš se, da storitve ne boš uporabljal za pošiljanje neželene pošte, zlonamerne programske opreme, phishing ali katerikoli nezakonit vsebinski. Ne poskušaj dostopati do računov drugih uporabnikov ali motiti infrastrukture storitve.',
  'terms.content.title': 'Lastništvo vsebine',
  'terms.content.body': 'Ohranjaš lastništvo vse vsebine, ki jo ustvariš in pošlješ preko storitve. Ne trdimo, da imamo lastništvo nad tvojimi emaili ali priponkami. Vsebino lahko obdelujemo, kot je potrebno za zagotavljanje storitve.',
  'terms.limitation.title': 'Omejitev odgovornosti',
  'terms.limitation.body': 'Chatyy se nudi "kot je". Stremimo k 99,9% razpoložljivosti, vendar ne zagotavljamo neprekinjene storitve. Nismo odgovorni za posredne, naključne ali posledične škode, ki izhajajo iz uporabe storitve.',
  'terms.termination.title': 'Prekinitev računa',
  'terms.termination.body': 'Lahko suspendiramo ali prekinemo račune, ki kršijo te pogoje. Svoj račun lahko izbrišeš kadarkoli v Nastavitvah. Po prekinitvi bodo tvoji podatki izbrisani v 30 dneh.',
  'terms.changes.title': 'Spremembe pogojev',
  'terms.changes.body': 'Te pogoje lahko občasno posodobimo. O pomembnih spremembah te bomo obvestili po emailu ali obvestilu v aplikaciji. Nadaljnja uporaba po spremembah pomeni sprejemanje posodobljenih pogojev.',
