  'plans.faqWhatIsPlusAnswer': 'To je premium načrt Chatyy, ki ščiti vse tvoje pogovore, fotografije in videoposnetke. S Chatyy One, tudi če kaj pomotoma izbrišeš, lahko obnoviš v 30 dneh. Poleg tega dobiš 200GB shranjevanja, One AI kot osebnega asistenta, in lahko pošlješ datoteke do 100MB.',
  'plans.faqCancelAnswer': 'Tvoj načrt ostane aktiven do konca plačanega obdobja. Po tem se vrneš na brezplačni načrt. Tvoje fotografije in videoposnetki, ki presegajo 15GB, bodo shranjeni še 30 dni, da jih lahko preneseš.',
